// humble shell: no decisions, just decode, delegate, encode
func (h *Handler) withdraw(w http.ResponseWriter, r *http.Request) {
    req, err := decodeWithdraw(r)
    if err != nil {
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }
    receipt, err := h.accounts.Withdraw(r.Context(), req)  // service, tested directly
    writeJSON(w, receipt, err)
}
